import type {
  LiveSnapshot,
  PairedTrace,
  Plan,
  PlanRequest,
  ShadowEpisode,
  ShadowSummary,
  SourceReceipt,
  State,
} from "../api/types";

import { momentLabel, offsetTo, rebase } from "./clock";

// Generated by web/dev/build_fixtures.py from the real planner. Never hand-edit.
export interface ScenarioFixture {
  id: string;
  label: string;
  unit: string;
  unit_name: string;
  source: "fixture";
  request: PlanRequest;
  state: State;
  plan: Plan;
  trace: PairedTrace | null;
}

export interface LiveFixture {
  snapshot: LiveSnapshot;
  episode: ShadowEpisode;
  stale_episode: ShadowEpisode;
  summary: ShadowSummary;
}

export interface FixtureBundle {
  scenarios: ScenarioFixture[];
  live: LiveFixture;
  quality: SourceReceipt;
}

// Order = unit order in the switcher, then situation order within a unit.
const ORDER = ["nominal", "perturbations", "peak", "incomplete", "garde", "geriatrie", "interne", "pneumologie"];

export async function loadFixtures(): Promise<FixtureBundle> {
  const modules = import.meta.glob<{ default: unknown }>("../fixtures/scenario-*.json");
  const scenarios = await Promise.all(
    ORDER.map(async (id) => {
      const load = modules[`../fixtures/scenario-${id}.json`];
      if (!load) throw new Error(`Missing fixture ${id}`);
      return (await load()).default as ScenarioFixture;
    }),
  );
  const [live, quality] = await Promise.all([
    import("../fixtures/live.json"),
    import("../fixtures/quality.json"),
  ]);
  const bundle: FixtureBundle = {
    scenarios,
    live: live.default as unknown as LiveFixture,
    quality: quality.default as unknown as SourceReceipt,
  };
  // The as-of instant and civil dates are part of the plan identity. Replay them verbatim.
  return bundle;
}

/**
 * The whole bundle moves by one offset (the first situation lands on now, to 5 minutes), so
 * units, replayed observation and data receipts stay mutually consistent. See clock.ts.
 */
export function toNow(bundle: FixtureBundle, now: number): FixtureBundle {
  const anchor = bundle.scenarios[0]?.state.at;
  if (!anchor) return bundle;
  const moved = rebase(bundle, offsetTo(anchor, now, 5));
  return {
    ...moved,
    scenarios: moved.scenarios.map((s) => ({ ...s, label: momentLabel(s.label, s.state.at) })),
  };
}
